?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Comisiones PROA — Hache Natación</title><style>
:root{--ink:#172033;--muted:#6b778b;--line:#e6ebf1;--paper:#fff;--bg:#f3f6fa;--brand:#123b5d;--ok:#166534;--okbg:#ecfdf3;--warn:#92400e;--warnbg:#fff7ed;--danger:#991b1b;--dangerbg:#fff1f2}
*{box-sizing:border-box}body{margin:0;background:var(--bg);font-family:Inter,Manrope,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:var(--ink)}.wrap{max-width:980px;margin:auto;padding:86px 16px 36px}.eyebrow{font-size:11px;font-weight:900;letter-spacing:.12em;text-transform:uppercase;color:#567089}.head h1{font-size:30px;line-height:1.1;margin:6px 0 7px;letter-spacing:-.025em}.sub{color:var(--muted);font-size:15px;line-height:1.5;margin-bottom:22px}.toolbar,.panel,.status{background:var(--paper);border:1px solid var(--line);border-radius:17px;box-shadow:0 8px 28px rgba(15,23,42,.04)}.toolbar{display:grid;grid-template-columns:minmax(180px,260px) 1fr;gap:12px;align-items:center;padding:13px;margin-bottom:12px}.toolbar input,.field input,.field textarea,.form button{width:100%;min-height:44px;padding:10px 12px;border:1px solid #cbd5e1;border-radius:11px;font:inherit}.toolbar-note{color:var(--muted);font-size:12px;line-height:1.5}.status{padding:16px;margin-bottom:12px;display:flex;justify-content:space-between;gap:14px;align-items:center}.status.ok{border-color:#bbf7d0;background:linear-gradient(135deg,#fff,#f0fdf4)}.status.no{border-color:#fed7aa;background:linear-gradient(135deg,#fff,#fff7ed)}.status-title{font-size:20px;font-weight:900;letter-spacing:-.025em}.status-meta{font-size:12px;color:var(--muted);margin-top:4px}.status-badge{padding:7px 10px;border-radius:999px;font-size:10px;font-weight:900;text-transform:uppercase;letter-spacing:.05em}.status.ok .status-badge{background:var(--okbg);color:var(--ok)}.status.no .status-badge{background:var(--warnbg);color:var(--warn)}.panel{padding:18px}.section-head{display:flex;justify-content:space-between;align-items:end;gap:10px;margin-bottom:14px}.section-head h2{margin:0;font-size:19px;letter-spacing:-.02em}.section-head span{font-size:12px;color:var(--muted)}.form{display:grid;grid-template-columns:1.3fr .55fr 1fr auto;gap:9px;align-items:end;padding:14px;background:#f8fafc;border:1px solid var(--line);border-radius:14px}.field label{display:block;font-size:10px;text-transform:uppercase;letter-spacing:.06em;font-weight:900;color:var(--muted);margin-bottom:6px}.form button{background:var(--ink);color:#fff;font-weight:850;border:0;cursor:pointer;padding-left:16px;padding-right:16px}.form button:disabled{opacity:.45;cursor:not-allowed}.form.is-locked{opacity:.55}.msg{margin-top:8px;font-size:12px;font-weight:750;min-height:18px}.msg.bad{color:var(--danger)}.msg.good{color:var(--ok)}.list{display:grid;gap:8px;margin-top:14px}.row{display:grid;grid-template-columns:1.2fr .45fr 1fr auto;gap:10px;align-items:center;padding:11px 12px;border:1px solid var(--line);border-radius:12px}.row.head{background:#f7f9fb;border:0;font-size:10px;font-weight:900;text-transform:uppercase;letter-spacing:.05em;color:var(--muted)}.amount{font-weight:900}.danger{border:0;background:var(--dangerbg);color:var(--danger);border-radius:9px;padding:8px 10px;font-weight:850;cursor:pointer}.total-card{margin-top:14px;padding:14px;border-radius:14px;background:linear-gradient(145deg,#172033,#20344e);color:#fff;display:flex;justify-content:space-between;align-items:end;gap:10px}.total-card span{font-size:11px;text-transform:uppercase;letter-spacing:.06em;color:#c9d5e3;font-weight:900}.total-card strong{font-size:27px;letter-spacing:-.035em}.empty{padding:20px;text-align:center;border:1px dashed #cbd5e1;border-radius:12px;color:var(--muted);font-size:13px}
@media(max-width:760px){.wrap{padding:80px 12px 28px}.head h1{font-size:27px}.toolbar{grid-template-columns:1fr}.status{align-items:flex-start;flex-direction:column}.form{grid-template-columns:1fr}.row.head{display:none}.row{grid-template-columns:1fr 1fr}.row>div:first-child{grid-column:1/-1;font-size:15px;font-weight:900;padding-bottom:7px;border-bottom:1px solid var(--line)}.row>div:not(:first-child)::before{content:attr(data-label);display:block;font-size:9px;text-transform:uppercase;letter-spacing:.05em;color:var(--muted);font-weight:900;margin-bottom:3px}.row .danger{justify-self:end}.total-card strong{font-size:24px}}
</style></head><body><main class="wrap"><header class="head"><div class="eyebrow">Finanzas privadas · ADMIN</div><h1>Comisiones PROA</h1><div class="sub">Registro nominal de las comisiones que PROA reconoce a Hache Natación.</div></header><div class="toolbar"><input id="periodo" type="month"><div class="toolbar-note">Las comisiones de un mes solo se habilitan cuando el aporte a PROA del mes anterior alcanzó el mínimo contractual.</div></div><div id="status" class="status"></div><section class="panel"><div class="section-head"><div><div class="eyebrow">Registro mensual</div><h2>Comisiones por alumno PROA</h2></div><span id="count"></span></div><div id="form" class="form"><div class="field"><label>Alumno PROA</label><input id="nombre" placeholder="Nombre completo"></div><div class="field"><label>Comisión</label><input id="importe" type="number" min="0" step="0.01" placeholder="500"></div><div class="field"><label>Observación</label><input id="obs" placeholder="Opcional"></div><button id="guardar">Registrar</button></div><div id="msg" class="msg"></div><div id="rows" class="list"></div><div class="total-card"><span>Total comisiones del mes</span><strong id="total">$0</strong></div></section></main><script>
const p=document.getElementById('periodo'),s=document.getElementById('status'),rows=document.getElementById('rows'),total=document.getElementById('total'),btn=document.getElementById('guardar'),msg=document.getElementById('msg'),form=document.getElementById('form'),count=document.getElementById('count');const money=n=>Number(n||0).toLocaleString('es-MX',{style:'currency',currency:'MXN',maximumFractionDigits:0});const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const monthLabel=v=>new Date(v+'-02T12:00:00').toLocaleDateString('es-MX',{month:'long',year:'numeric'});p.value=new Date().toISOString().slice(0,7);function flash(t,type=''){msg.textContent=t;msg.className='msg '+type}async function load(){flash('');try{const r=await fetch('/api/comisiones-proa.php?periodo='+encodeURIComponent(p.value),{cache:'no-store'}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'No se pudo cargar.');btn.disabled=!d.habilitado;form.classList.toggle('is-locked',!d.habilitado);s.className='status '+(d.habilitado?'ok':'no');s.innerHTML=d.habilitado?`<div><div class="status-title">Comisiones habilitadas</div><div class="status-meta">${esc(monthLabel(d.periodo_generador))} alcanzó el mínimo de ${money(d.minimo)}.</div></div><span class="status-badge">Disponible ✓</span>`:`<div><div class="status-title">Comisiones no habilitadas</div><div class="status-meta">Aporte de ${esc(monthLabel(d.periodo_generador))}: ${money(d.aporte_periodo_generador)} de ${money(d.minimo)}.</div></div><span class="status-badge">Bloqueado</span>`;count.textContent=`${d.comisiones.length} registro${d.comisiones.length===1?'':'s'}`;rows.innerHTML=d.comisiones.length?`<div class="row head"><div>Alumno PROA</div><div>Comisión</div><div>Observación</div><div></div></div>`+d.comisiones.map(x=>`<div class="row"><div>${esc(x.alumno_proa_nombre)}</div><div class="amount" data-label="Comisión">${money(x.importe)}</div><div data-label="Observación">${esc(x.observacion||'—')}</div><div data-label="Acción"><button class="danger" data-del="${x.id}">Eliminar</button></div></div>`).join(''):`<div class="empty">No hay comisiones registradas para este mes.</div>`;total.textContent=money(d.total)}catch(e){s.className='status no';s.innerHTML=`<div><div class="status-title">No se pudo cargar</div><div class="status-meta">${esc(e.message||'Error')}</div></div><span class="status-badge">Error</span>`;rows.innerHTML='';total.textContent=money(0)}}p.onchange=load;btn.onclick=async()=>{flash('');const body={periodo:p.value,alumno_proa_nombre:document.getElementById('nombre').value.trim(),importe:Number(document.getElementById('importe').value||0),observacion:document.getElementById('obs').value.trim()};try{const r=await fetch('/api/comisiones-proa.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'No se pudo registrar');document.getElementById('nombre').value='';document.getElementById('importe').value='';document.getElementById('obs').value='';flash('Comisión registrada.','good');await load()}catch(e){flash(e.message||'No se pudo registrar','bad')}};rows.onclick=async e=>{const b=e.target.closest('[data-del]');if(!b||!confirm('¿Eliminar esta comisión?'))return;try{const r=await fetch('/api/comisiones-proa.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({accion:'ELIMINAR',id:b.dataset.del})}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Error');await load()}catch(e){flash(e.message||'Error','bad')}};load();
</script></body></html>